# November 19, 2026: a first scatter of places across Iowa, which had one place on the map (the Hurstville lime kilns).
# Region ia claimed with tools/choose.py --thinnest. Sources opened in this session: Wikipedia as raw text
# (tools/wiki_raw.py); the managing bodies' own pages read with tools/page.py (Iowa DNR park pages, the State Historical
# Society of Iowa, Clayton County Conservation and motormill.org, the Buchanan County Historical Society, the Historical
# Society of Pottawattamie County, the University of Iowa's Old Capitol Museum, Terrace Hill, Wright on the Park,
# Woodbury County, Villages of Van Buren and its Bentonsport walking-tour brochure, Madison County Tourism and the Iowa
# DOT historic bridge page); HMdb marker pages for the Dubuque Shot Tower and Buxton.
from data_b import N
from data_ma import W
